import{_ as l,a0 as d,w as o,s as h,ao as p,I as t,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const m=JSON.parse('{"title":"为什么 0.1 + 0.2 = 0.30000000000000004？ | LCTT x X-CMD","titleTemplate":false,"description":"为什么 0.1 + 0.2 = 0.30000000000000004？ | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么 0.1 + 0.2 = 0.30000000000000004？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么 0.1 + 0.2 = 0.30000000000000004？ | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230208.3 ⭐️⭐️⭐️ Why does 0.1 + 0.2 = 0.30000000000000004","title":"为什么 0.1 + 0.2 = 0.30000000000000004？","tag":"202305","desc":""},"relativePath":"202305/20230208.3 ⭐️⭐️⭐️ Why does 0.1 + 0.2 = 0.30000000000000004.md","filePath":"[post].md"}'),c={name:"202305/20230208.3 ⭐️⭐️⭐️ Why does 0.1 + 0.2 = 0.30000000000000004.md"};function g(r,s,k,b,u,f){const e=d("Link");return o(),h("div",null,[s[23]||(s[23]=p(`<h1 id="为什么-0-1-0-2-0-30000000000000004" tabindex="-1">为什么 0.1 + 0.2 = 0.30000000000000004？ <a class="header-anchor" href="#为什么-0-1-0-2-0-30000000000000004" aria-label="Permalink to “为什么 0.1 + 0.2 = 0.30000000000000004？”">​</a></h1><p>嗨！昨天我试着写点关于浮点数的东西，我发现自己对这个 64 位浮点数的计算方法很好奇：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 0.1 + 0.2</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><p>我意识到我并没有完全理解它是如何计算的。我的意思是，我知道浮点计算是不精确的，你不能精确地用二进制表示 <code>0.1</code>，但是：肯定有一个浮点数比 <code>0.30000000000000004</code> 更接近 0.3！那为什么答案是 <code>0.30000000000000004</code> 呢？</p><p>如果你不想阅读一大堆计算过程，那么简短的答案是： <code>0.1000000000000000055511151231257827021181583404541015625 + 0.200000000000000011102230246251565404236316680908203125</code> 正好位于两个浮点数之间，即 <code>0.299999999999999988897769753748434595763683319091796875</code> （通常打印为 <code>0.3</code>） 和 <code>0.3000000000000000444089209850062616169452667236328125</code>（通常打印为 <code>0.30000000000000004</code>）。答案是 <code>0.30000000000000004</code>，因为它的尾数是偶数。</p><h4 id="浮点加法是如何计算的" tabindex="-1">浮点加法是如何计算的 <a class="header-anchor" href="#浮点加法是如何计算的" aria-label="Permalink to “浮点加法是如何计算的”">​</a></h4><p>以下是浮点加法的简要计算原理：</p><ul><li>把它们精确的数字加在一起</li><li>将结果四舍五入到最接近的浮点数</li></ul><p>让我们用这些规则来计算 0.1 + 0.2。我昨天才刚了解浮点加法的计算原理，所以在这篇文章中我可能犯了一些错误，但最终我得到了期望的答案。</p><h4 id="第一步-0-1-和-0-2-到底是多少" tabindex="-1">第一步：0.1 和 0.2 到底是多少 <a class="header-anchor" href="#第一步-0-1-和-0-2-到底是多少" aria-label="Permalink to “第一步：0.1 和 0.2 到底是多少”">​</a></h4><p>首先，让我们用 Python 计算 <code>0.1</code> 和 <code>0.2</code> 的 64 位浮点值。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; f&quot;{0.1:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.10000000000000000555111512312578270211815834045410156250000000000000000000000000&#39;</span></span>
<span class="line"><span>&gt;&gt;&gt; f&quot;{0.2:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.20000000000000001110223024625156540423631668090820312500000000000000000000000000&#39;</span></span></code></pre></div><p>这确实很精确：因为浮点数是二进制的，你也可以使用十进制来精确的表示。但有时你只是需要一大堆数字:)</p><h4 id="第二步-相加" tabindex="-1">第二步：相加 <a class="header-anchor" href="#第二步-相加" aria-label="Permalink to “第二步：相加”">​</a></h4><p>接下来，把它们加起来。我们可以将小数部分作为整数加起来得到确切的答案：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 1000000000000000055511151231257827021181583404541015625 + 2000000000000000111022302462515654042363166809082031250</span></span>
<span class="line"><span>3000000000000000166533453693773481063544750213623046875</span></span></code></pre></div><p>所以这两个浮点数的和是 <code>0.3000000000000000166533453693773481063544750213623046875</code>。</p><p>但这并不是最终答案，因为它不是一个 64 位浮点数。</p><h4 id="第三步-查找最接近的浮点数" tabindex="-1">第三步：查找最接近的浮点数 <a class="header-anchor" href="#第三步-查找最接近的浮点数" aria-label="Permalink to “第三步：查找最接近的浮点数”">​</a></h4><p>现在，让我们看看接近 <code>0.3</code> 的浮点数。下面是最接近 <code>0.3</code> 的浮点数（它通常写为 <code>0.3</code>，尽管它不是确切值）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; f&quot;{0.3:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.29999999999999998889776975374843459576368331909179687500000000000000000000000000&#39;</span></span></code></pre></div><p>我们可以通过 <code>struct.pack</code> 将 <code>0.3</code> 序列化为 8 字节来计算出它之后的下一个浮点数，加上 1，然后使用 <code>struct.unpack</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; struct.pack(&quot;!d&quot;, 0.3)</span></span>
<span class="line"><span>b&#39;?\\xd3333333&#39;</span></span>
<span class="line"><span># 手动加 1</span></span>
<span class="line"><span>&gt;&gt;&gt; next_float = struct.unpack(&quot;!d&quot;, b&#39;?\\xd3333334&#39;)[0]</span></span>
<span class="line"><span>&gt;&gt;&gt; next_float</span></span>
<span class="line"><span>0.30000000000000004</span></span>
<span class="line"><span>&gt;&gt;&gt; f&quot;{next_float:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.30000000000000004440892098500626161694526672363281250000000000000000000000000000&#39;</span></span></code></pre></div><p>当然，你也可以用 <code>math.nextafter</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; math.nextafter(0.3, math.inf)</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><p>所以 <code>0.3</code> 附近的两个 64 位浮点数是 <code>0.299999999999999988897769753748434595763683319091796875</code> 和 <code>0.3000000000000000444089209850062616169452667236328125</code>。</p><h4 id="第四步-找出哪一个最接近" tabindex="-1">第四步：找出哪一个最接近 <a class="header-anchor" href="#第四步-找出哪一个最接近" aria-label="Permalink to “第四步：找出哪一个最接近”">​</a></h4><p>结果证明 <code>0.3000000000000000166533453693773481063544750213623046875</code> 正好在 <code>0.299999999999999988897769753748434595763683319091796875</code> 和 <code>0.3000000000000000444089209850062616169452667236328125</code> 的中间。</p><p>你可以通过以下计算看到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; (3000000000000000444089209850062616169452667236328125000 + 2999999999999999888977697537484345957636833190917968750) // 2 == 3000000000000000166533453693773481063544750213623046875</span></span>
<span class="line"><span>True</span></span></code></pre></div><p>所以它们都不是最接近的。</p><h4 id="如何知道四舍五入到哪一个" tabindex="-1">如何知道四舍五入到哪一个？ <a class="header-anchor" href="#如何知道四舍五入到哪一个" aria-label="Permalink to “如何知道四舍五入到哪一个？”">​</a></h4><p>在浮点数的二进制表示中，有一个数字称为“尾数”。这种情况下（结果正好在两个连续的浮点数之间），它将四舍五入到偶数尾数的那个。</p><p>在本例中为 <code>0.300000000000000044408920985006261616945266723632812500</code>。</p><p>我们之前就见到了这个数字的尾数：</p><ul><li>0.30000000000000004 是 <code>struct.unpack(&#39;!d&#39;, b&#39;?\\xd3333334&#39;)</code> 的结果</li><li>0.3 是 <code>struct.unpack(&#39;!d&#39;, b&#39;?\\xd3333333&#39;)</code> 的结果</li></ul><p><code>0.30000000000000004</code> 的大端十六进制表示的最后一位数字是 <code>4</code>，它的尾数是偶数（因为尾数在末尾）。</p><h4 id="我们用二进制来算一下" tabindex="-1">我们用二进制来算一下 <a class="header-anchor" href="#我们用二进制来算一下" aria-label="Permalink to “我们用二进制来算一下”">​</a></h4><p>之前我们都是使用十进制来计算的，这样读起来更直观。但是计算机并不会使用十进制，而是用 2 进制，所以我想知道它是如何计算的。</p><p>我不认为本文的二进制计算部分特别清晰，但它写出来对我很有帮助。有很多数字，读起来可能很糟糕。</p><h4 id="_64-位浮点数如何计算-指数和尾数" tabindex="-1">64 位浮点数如何计算：指数和尾数 <a class="header-anchor" href="#_64-位浮点数如何计算-指数和尾数" aria-label="Permalink to “64 位浮点数如何计算：指数和尾数”">​</a></h4><p>64 位浮点数由 2 部分整数构成：<strong>指数</strong>和<strong>尾数</strong>，还有 1 比特 <strong>符号位</strong>.</p><p>以下是指数和尾数对应于实际数字的方程：</p><p>$$\\text{sign} \\times 2^\\text{exponent} (1 + \\frac{\\text{significand}}{2^{52}})$$</p><p>例如，如果指数是 <code>1</code>，尾数是 <code>2**51</code>，符号位是正的，那么就可以得到：</p><p>$$2^{1} (1 + \\frac{2^{51}}{2^{52}})$$</p><p>它等于 <code>2 * (1 + 0.5)</code>，即 3。</p><h4 id="步骤-1-获取-0-1-和-0-2-的指数和尾数" tabindex="-1">步骤 1：获取 0.1 和 0.2 的指数和尾数 <a class="header-anchor" href="#步骤-1-获取-0-1-和-0-2-的指数和尾数" aria-label="Permalink to “步骤 1：获取 0.1 和 0.2 的指数和尾数”">​</a></h4><p>我用 Python 编写了一些低效的函数来获取正浮点数的指数和尾数:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def get_exponent(f):</span></span>
<span class="line"><span>    # 获取前 52 个字节</span></span>
<span class="line"><span>    bytestring = struct.pack(&#39;!d&#39;, f)</span></span>
<span class="line"><span>    return int.from_bytes(bytestring, byteorder=&#39;big&#39;) &gt;&gt; 52</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def get_significand(f):</span></span>
<span class="line"><span>    # 获取后 52 个字节</span></span>
<span class="line"><span>    bytestring = struct.pack(&#39;!d&#39;, f)</span></span>
<span class="line"><span>    x = int.from_bytes(bytestring, byteorder=&#39;big&#39;)</span></span>
<span class="line"><span>    exponent = get_exponent(f)</span></span>
<span class="line"><span>    return x ^ (exponent &lt;&lt; 52)</span></span></code></pre></div><p>我忽略了符号位（第一位），因为我们只需要处理 0.1 和 0.2，它们都是正数。</p><p>首先，让我们获取 0.1 的指数和尾数。我们需要减去 1023 来得到实际的指数，因为浮点运算就是这么计算的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; get_exponent(0.1) - 1023</span></span>
<span class="line"><span>-4</span></span>
<span class="line"><span>&gt;&gt;&gt; get_significand(0.1)</span></span>
<span class="line"><span>2702159776422298</span></span></code></pre></div><p>它们根据 <code>2**指数 + 尾数 / 2**(52 - 指数)</code> 这个公式得到 <code>0.1</code>。</p><p>下面是 Python 中的计算:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**-4 + 2702159776422298 / 2**(52 + 4)</span></span>
<span class="line"><span>0.1</span></span></code></pre></div><p>（你可能会担心这种计算的浮点精度问题，但在本例中，我很确定它没问题。因为根据定义，这些数字没有精度问题 -- 从 <code>2**-4</code> 开始的浮点数以 <code>1/2**(52 + 4)</code> 步长递增。）</p><p><code>0.2</code> 也一样:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; get_exponent(0.2) - 1023</span></span>
<span class="line"><span>-3</span></span>
<span class="line"><span>&gt;&gt;&gt; get_significand(0.2)</span></span>
<span class="line"><span>2702159776422298</span></span></code></pre></div><p>它们共同工作得到 <code>0.2</code>:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**-3 + 2702159776422298 / 2**(52 + 3)</span></span>
<span class="line"><span>0.2</span></span></code></pre></div><p>（顺便说一下，0.1 和 0.2 具有相同的尾数并不是巧合 —— 因为 <code>x</code> 和 <code>2*x</code> 总是有相同的尾数。）</p><h4 id="步骤-2-重新计算-0-1-以获得更大的指数" tabindex="-1">步骤 2：重新计算 0.1 以获得更大的指数 <a class="header-anchor" href="#步骤-2-重新计算-0-1-以获得更大的指数" aria-label="Permalink to “步骤 2：重新计算 0.1 以获得更大的指数”">​</a></h4><p><code>0.2</code> 的指数比 <code>0.1</code> 大 -- -3 大于 -4。</p><p>所以我们需要重新计算：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-4 + 2702159776422298 / 2**(52 + 4)</span></span></code></pre></div><p>等于 <code>X / (2**52 + 3)</code></p><p>如果我们解出 <code>2**-4 + 2702159776422298 / 2**(52 + 4) = X / (2**52 + 3)</code>，我们能得到：</p><p><code>X = 2**51 + 2702159776422298 /2</code></p><p>在 Python 中，我们很容易得到：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**51 + 2702159776422298 //2</span></span>
<span class="line"><span>3602879701896397</span></span></code></pre></div><h4 id="步骤-3-添加符号位" tabindex="-1">步骤 3：添加符号位 <a class="header-anchor" href="#步骤-3-添加符号位" aria-label="Permalink to “步骤 3：添加符号位”">​</a></h4><p>现在我们试着做加法：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-3 + 2702159776422298 / 2**(52 + 3) + 3602879701896397 / 2**(52 + 3)</span></span></code></pre></div><p>我们需要将 <code>2702159776422298</code> 和 <code>3602879701896397</code> 相加：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2702159776422298  + 3602879701896397</span></span>
<span class="line"><span>6305039478318695</span></span></code></pre></div><p>棒。但是 <code>6305039478318695</code> 比 <code>2**52-1</code>（尾数的最大值）大，问题来了:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 6305039478318695 &gt; 2**52</span></span>
<span class="line"><span>True</span></span></code></pre></div><h4 id="第四步-增加指数" tabindex="-1">第四步：增加指数 <a class="header-anchor" href="#第四步-增加指数" aria-label="Permalink to “第四步：增加指数”">​</a></h4><p>目前结果是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-3 + 6305039478318695 / 2**(52 + 3)</span></span></code></pre></div><p>首先，它减去 2**52：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>2**-2 + 1801439850948199 / 2**(52 + 3)</span></span></code></pre></div><p>完美，但最后的 <code>2**(52 + 3)</code> 需要改为 <code>2**(52 + 2)</code>。</p><p>我们需要将 <code>1801439850948199</code> 除以 2。这就是难题的地方 -- <code>1801439850948199</code> 是一个奇数!</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 1801439850948199  / 2</span></span>
<span class="line"><span>900719925474099.5</span></span></code></pre></div><p>它正好在两个整数之间，所以我们四舍五入到最接近它的偶数（这是浮点运算规范要求的），所以最终的浮点结果是:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 2**-2 + 900719925474100 / 2**(52 + 2)</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><p>它就是我们预期的结果：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; 0.1 + 0.2</span></span>
<span class="line"><span>0.30000000000000004</span></span></code></pre></div><h4 id="在硬件中它可能并不是这样工作的" tabindex="-1">在硬件中它可能并不是这样工作的 <a class="header-anchor" href="#在硬件中它可能并不是这样工作的" aria-label="Permalink to “在硬件中它可能并不是这样工作的”">​</a></h4><p>在硬件中做浮点数加法，以上操作方式可能并不完全一模一样（例如，它并不是求解 “X”），我相信有很多有效的技巧，但我认为思想是类似的。</p><h4 id="打印浮点数是非常奇怪的" tabindex="-1">打印浮点数是非常奇怪的 <a class="header-anchor" href="#打印浮点数是非常奇怪的" aria-label="Permalink to “打印浮点数是非常奇怪的”">​</a></h4><p>我们之前说过，浮点数 0.3 不等于 0.3。它实际上是:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&gt;&gt;&gt; f&quot;{0.3:.80f}&quot;</span></span>
<span class="line"><span>&#39;0.29999999999999998889776975374843459576368331909179687500000000000000000000000000&#39;</span></span></code></pre></div><p>但是当你打印它时，为什么会显示 <code>0.3</code>？</p><p>计算机实际上并没有打印出数字的精确值，而是打印出了<em>最短</em>的十进制数 <code>d</code>，其中 <code>f</code> 是最接近 <code>d</code> 的浮点数。</p>`,97)),t("p",null,[s[2]||(s[2]=a("事实证明，有效做到这一点很不简单，有很多关于它的学术论文，比如 ",-1)),i(e,{href:"https://legacy.cs.indiana.edu/~dyb/pubs/FP-Printing-PLDI96.pdf"},{default:n(()=>[...s[0]||(s[0]=[a("快速且准确地打印浮点数",-1)])]),_:1}),s[3]||(s[3]=a("、",-1)),i(e,{href:"https://lists.nongnu.org/archive/html/gcl-devel/2012-10/pdfkieTlklRzN.pdf"},{default:n(()=>[...s[1]||(s[1]=[a("如何准确打印浮点数",-1)])]),_:1}),s[4]||(s[4]=a(" 等。",-1))]),s[24]||(s[24]=p('<h4 id="如果计算机打印出浮点数的精确值-会不会更直观一些" tabindex="-1">如果计算机打印出浮点数的精确值，会不会更直观一些？ <a class="header-anchor" href="#如果计算机打印出浮点数的精确值-会不会更直观一些" aria-label="Permalink to “如果计算机打印出浮点数的精确值，会不会更直观一些？”">​</a></h4><p>四舍五入到一个干净的十进制值很好，但在某种程度上，我觉得如果计算机只打印一个浮点数的精确值可能会更直观 -- 当你得到一个奇怪的结果时，它可能会让你看起来不那么惊讶。</p><p>对我来说，<code>0.1000000000000000055511151231257827021181583404541015625 + 0.200000000000000011102230246251565404236316680908203125 = 0.3000000000000000444089209850062616169452667236328125</code> 比 <code>0.1 + 0.2 = 0.30000000000000000004</code> 惊讶少一点。</p><p>这也许是一个坏主意，因为它肯定会占用大量的屏幕空间。</p><h4 id="php-快速说明" tabindex="-1">PHP 快速说明 <a class="header-anchor" href="#php-快速说明" aria-label="Permalink to “PHP 快速说明”">​</a></h4><p>有人在评论中指出在 PHP 中 <code>&lt;?php echo (0.1 + 0.2 );?&gt;</code> 会输出 <code>0.3</code>，这是否说明在 PHP 中浮点运算不一样？</p>',6)),t("p",null,[s[6]||(s[6]=a("非也 —— 我在 ",-1)),i(e,{href:"https://replit.com/languages/php_cli"},{default:n(()=>[...s[5]||(s[5]=[a("这里",-1)])]),_:1}),s[7]||(s[7]=a(" 运行:",-1))]),s[25]||(s[25]=p('<p><code>&lt;?php echo (0.1 + 0.2 )- 0.3);?&gt;</code>，得到了与 Python 完全相同的答案：5.5511151231258E-17。因此，浮点运算的基本原理是一样的。</p><p>我认为在 PHP 中 <code>0.1 + 0.2</code> 输出 <code>0.3</code> 的原因是 PHP 显示浮点数的算法没有 Python 精确 —— 即使这个数字不是最接近 0.3 的浮点数，它也会显示 <code>0.3</code>。</p><h4 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h4><p>我有点怀疑是否有人能耐心完成以上所有些算术，但它写出来对我很有帮助，所以我还是发表了这篇文章，希望它能有所帮助。</p><p><em>（题图：MJ/53e9a241-14c6-4dc7-87d0-f9801cd2d7ab）</em></p><hr>',6)),t("p",null,[s[9]||(s[9]=a("via: ",-1)),i(e,{href:"https://jvns.ca/blog/2023/02/08/why-does-0-1-plus-0-2-equal-0-30000000000000004/"},{default:n(()=>[...s[8]||(s[8]=[a("https://jvns.ca/blog/2023/02/08/why-does-0-1-plus-0-2-equal-0-30000000000000004/",-1)])]),_:1})]),t("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://jvns.ca/"},{default:n(()=>[...s[10]||(s[10]=[a("Julia Evans",-1)])]),_:1}),s[15]||(s[15]=a(" 选题：",-1)),i(e,{href:"https://github.com/lkxed/"},{default:n(()=>[...s[11]||(s[11]=[a("lkxed",-1)])]),_:1}),s[16]||(s[16]=a(" 译者：",-1)),i(e,{href:"https://github.com/MjSeven"},{default:n(()=>[...s[12]||(s[12]=[a("MjSeven",-1)])]),_:1}),s[17]||(s[17]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[19]||(s[19]=[a("Linux中国",-1)])]),_:1}),s[22]||(s[22]=a(" 荣誉推出",-1))])])}const C=l(c,[["render",g]]);export{m as __pageData,C as default};
